```python
# 第一步：领域层定义接口
# domain/repositories/order_repository.py
from abc import ABC, abstractmethod
class OrderRepository(ABC):
    @abstractmethod
    def get(self, order_id: str): ...
    @abstractmethod
    def save(self, order): ...
# 第二步：基础设施层实现接口
# infrastructure/persistence/sqlalchemy_order_repository.py
from domain.repositories.order_repository import OrderRepository
class SqlAlchemyOrderRepository(OrderRepository):
    def get(self, order_id: str):
        ...  # SQL 实现
    def save(self, order):
        ...  # SQL 实现
# 第三步：应用层依赖接口而非具体实现
# application/services/order_application_service.py
class OrderApplicationService:
    def __init__(self, order_repo: OrderRepository):
        self._repo = order_repo
# 第四步：组合根（main.py）注入具体实现
def create_order_service():
    repo = SqlAlchemyOrderRepository(create_db_session())
    return OrderApplicationService(repo)
```

以「取消订单」为例，看三层代码各自该做什么：

```python
# 接口层：只做协议转换，不写业务规则
@router.post("/orders/{order_id}/cancel")
async def cancel_order(order_id: str, body: CancelOrderRequest):
    command = CancelOrderCommand(order_id=order_id, reason=body.reason)
    order_service.cancel_order(command)
    return Response(status_code=204)
# 应用层：只做步骤编排，不写规则细节
class OrderApplicationService:
    def cancel_order(self, command):
        order = self._repo.get(command.order_id)   # 加载
        order.cancel(command.reason)                # 领域操作
        self._repo.save(order)                      # 持久化
        self._publish_events(order)                 # 发事件
# 领域层：只写业务规则，不碰数据库
class Order:
    def cancel(self, reason: str):
        if self._status == OrderStatus.SHIPPED:
            raise OrderException("已发货订单不可取消")
        self._status = OrderStatus.CANCELLED
        self._cancel_reason = reason
```

**端口**是应用核心定义的接口，分两种方向：

**驱动端口（Primary Port）**——核心对外提供的功能接口，被外部（HTTP、CLI、测试）调用。它描述「我能做什么」。

**被驱动端口（Secondary Port）**——核心需要外部提供的能力接口，由基础设施适配器实现。它描述「我需要什么」。

```python
# 驱动端口：核心提供的用例接口
from abc import ABC, abstractmethod
class OrderManagementPort(ABC):
    @abstractmethod
    def place_order(self, command) -> str: ...
    @abstractmethod
    def cancel_order(self, command) -> None: ...
# 被驱动端口：核心需要的依赖能力
class OrderStoragePort(ABC):
    @abstractmethod
    def save(self, order) -> None: ...
    @abstractmethod
    def get(self, order_id) -> object: ...
class PaymentGatewayPort(ABC):
    @abstractmethod
    def charge(self, amount, method) -> object: ...
```

**适配器**实现端口，把具体技术「适配」到核心需要的接口形状。

驱动适配器把外部请求翻译成对核心的调用——HTTP 适配器把 `POST /orders` 翻译成 `place_order(command)`；CLI 适配器把命令行输入翻译成同一个调用；Kafka 适配器把消息翻译成同一个调用。核心完全不知道请求是从哪里来的。

被驱动适配器把核心调用翻译成具体技术——PostgreSQL 适配器实现 `OrderStoragePort`，MongoDB 适配器也实现 `OrderStoragePort`，内存适配器同样实现 `OrderStoragePort`（专门用于测试）。核心完全不知道数据存在哪里。

```python
# 驱动适配器：HTTP
class FastAPIOrderAdapter:
    def __init__(self, port: OrderManagementPort):
        self._port = port
    def register_routes(self, app):
        @app.post("/orders")
        async def place_order(req):
            return {"order_id": self._port.place_order(req.to_command())}
# 被驱动适配器：内存存储（测试用）
class InMemoryOrderAdapter(OrderStoragePort):
    def __init__(self):
        self._store = {}
    def save(self, order):
        self._store[order.id] = order
    def get(self, order_id):
        return self._store[order_id]
```

进阶形式：写端用规范化数据库（PostgreSQL），读端用专门优化过的读存储（Elasticsearch、Redis 缓存或非规范化只读库）。两者通过**投影器（Projector）**同步：

```python
# 投影器：监听领域事件，更新读模型
class OrderProjector:
    def __init__(self, read_db):
        self._read_db = read_db
    def on_order_placed(self, event) -> None:
        self._read_db.upsert("order_views", {
            "order_id": event.order_id,
            "customer_id": event.customer_id,
            "status": "placed",
            "total": float(event.total_amount),
            "placed_at": event.occurred_at.isoformat(),
        })
    def on_order_shipped(self, event) -> None:
        self._read_db.update(
            "order_views",
            filter={"order_id": event.order_id},
            update={
                "status": "shipped",
                "tracking_number": event.tracking_number,
            }
        )
```

事件溯源聚合和普通聚合的关键区别：每个命令方法**不直接修改状态**，而是产生事件；`_when_*` 方法负责根据事件**纯粹地修改状态**（无业务规则，无副作用）：

```python
class Order(EventSourcedAggregate):
    def __init__(self):
        super().__init__()
        self._status = OrderStatus.NONE
        self._items = []
        self._total = 0
    # 命令方法：检查规则 → 产生事件
    def place(self):
        if not self._items:
            raise ValueError("订单为空")
        from decimal import Decimal
        total = sum(i["price"] * i["qty"] for i in self._items)
        self._record_event(OrderPlaced(
            aggregate_id=self._id,
            total_amount=Decimal(str(total))
        ))
    def cancel(self, reason: str):
        if self._status == OrderStatus.SHIPPED:
            raise ValueError("已发货订单不可取消")
        self._record_event(OrderCancelled(
            aggregate_id=self._id, reason=reason
        ))
    # 事件处理方法：只做状态变更，不做规则判断
    def _when_OrderPlaced(self, event):
        self._status = OrderStatus.PLACED
        self._total = event.total_amount
    def _when_OrderCancelled(self, event):
        self._status = OrderStatus.CANCELLED
```

事件存储（Event Store）本质上是一张只追加的日志表，每行是一个事件，带版本号：

```python
class EventStore:
    def append(self, aggregate_id: str, events: list,
               expected_version: int) -> None:
        current = self._get_current_version(aggregate_id)
        if current != expected_version:
            raise ConcurrencyException(
                f"乐观锁冲突：期望 {expected_version}，实际 {current}"
            )
        for i, event in enumerate(events):
            self._db.execute(
                "INSERT INTO event_store "
                "(aggregate_id, event_type, event_data, version) "
                "VALUES (:agg, :type, :data, :ver)",
                {"agg": aggregate_id,
                 "type": type(event).__name__,
                 "data": self._serialize(event),
                 "ver": current + i + 1}
            )
    def load(self, aggregate_id: str, from_version: int = 0) -> list:
        rows = self._db.execute(
            "SELECT event_type, event_data FROM event_store "
            "WHERE aggregate_id = :agg AND version > :ver "
            "ORDER BY version ASC",
            {"agg": aggregate_id, "ver": from_version}
        )
        return [self._deserialize(r["event_type"], r["event_data"])
                for r in rows]
```

`expected_version` 是乐观锁——保存时检查版本号，如果不符说明并发修改，直接报错，让上层重试。
